/** #vi-flow-ms: the pipeline measures, folded again only when the pipeline log changes. A
 *  ticket's size is the count of stories in its file (#lp-trend-size). */
let measuresMemo: { text: string; m: Measures } | undefined
function readMeasures(): Measures {
  const board = readBoard()
  const text = readText(PIPELINE_PATH) + '\n' + board.length + ':' + (board.at(-1)?.seq ?? 0)
  if (measuresMemo?.text === text) return measuresMemo.m
  const tickets = foldBoard(board).tickets
  const sizeOf = (id: string) => {
    const t = tickets.get(id)
    return t ? readTicketText(t)?.stories.length : undefined
  }
  measuresMemo = { text, m: measures(readPipeline(), sizeOf, board) }
  return measuresMemo.m
}
